import{_ as a}from"./chunks/daily-2026-08-22-codeflowmu-governance-state-rail-figure-1.Ckl_IW7w.js";import{_ as n,C as i,o,c as s,E as r,a2 as c}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"What Turns Multiple Agents into a Team? Governance, a File State Machine, and an Engineering Rail","description":"","frontmatter":{"title":"What Turns Multiple Agents into a Team? Governance, a File State Machine, and an Engineering Rail","date":"2026-08-22","column":"open-source-engineering","category":"daily","article_type":"architecture-explainer","edition":"research-center","research_question":"How do TMPA, FCoP, and CodeFlowMu divide responsibility and connect into a governable multi-agent system?","summary":"More model sessions do not automatically create a team. This article follows one accountable work item to show how TMPA defines governance semantics, FCoP externalizes state, and CodeFlowMu runs the engineering rail.","item_id":"MANUAL-20260822-CODEFLOWMU-GOVERNANCE-RAIL","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-22-codeflowmu-governance-state-rail-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-22-codeflowmu-rail-state-series-round1/02-source-register.md","research/manual-runs/2026-08-22-codeflowmu-rail-state-series-round1/02-fact-claim-matrices.md"]},"headers":[],"relativePath":"en/engineering/2026-08-22-codeflowmu-governance-state-rail.md","filePath":"en/engineering/2026-08-22-codeflowmu-governance-state-rail.md","lastUpdated":1787553126000}'),l={name:"en/engineering/2026-08-22-codeflowmu-governance-state-rail.md"};function d(h,e,p,u,m,g){const t=i("ArticleCover");return o(),s("div",null,[r(t,{image:"/assets/covers/daily-2026-08-22-codeflowmu-governance-state-rail-cover.png",kicker:"Open-source Engineering · Project Research",title:"What Turns Multiple Agents into a Team? Governance, a File State Machine, and an Engineering Rail",summary:"More sessions do not automatically create a team. TMPA sets governance semantics, FCoP preserves state facts, and CodeFlowMu performs engineering execution.",version:"MANUAL-20260822-CODEFLOWMU-GOVERNANCE-RAIL",status:"Editorial & Visual PASS · 2026-08-23",languageHref:"/zh/engineering/2026-08-22-codeflowmu-governance-state-rail",languageLabel:"中文"}),e[0]||(e[0]=c('<h1 id="what-turns-multiple-agents-into-a-team-governance-a-file-state-machine-and-an-engineering-rail" tabindex="-1">What Turns Multiple Agents into a Team? Governance, a File State Machine, and an Engineering Rail <a class="header-anchor" href="#what-turns-multiple-agents-into-a-team-governance-a-file-state-machine-and-an-engineering-rail" aria-label="Permalink to &quot;What Turns Multiple Agents into a Team? Governance, a File State Machine, and an Engineering Rail&quot;">​</a></h1><p>Imagine a multi-agent delivery in which the development agent says the code is done, the QA agent says the tests passed, and the PM agent produces a final summary. Then someone asks three basic questions: Which code revision did QA test? Who was authorized to accept the result? Where should the work resume after a process restart?</p><p>The three sessions return three different answers.</p><p>The problem is not a shortage of agents. The agents were answering in parallel, but they were not operating as an accountable team.</p><p>The central argument of this article is that a multi-agent team needs at least three distinct layers: <strong>a governance model that defines legitimate collaboration, a file state machine that externalizes current facts and transition history, and an engineering rail that performs dispatch, execution, observation, and recovery.</strong> By the end, you should be able to draw the same responsibility map for your own system and identify where policy, fact, execution, and final judgment actually live.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Series order (1/3).</strong> This article defines the three responsibility layers. <a href="./2026-08-22-agent-task-file-state-machine">Part 2</a> examines the TASK file state machine, atomic transitions, and concurrency boundary. <a href="./../digital-employee/2026-08-22-agent-rail-decision-boundary">Part 3</a> separates mechanical rail behavior from decisions that belong to an agent, PM, or ADMIN. The three articles share one vocabulary and evidence boundary; none should be read alone as a complete implementation claim.</p></div><h2 id="three-layers-three-different-jobs" tabindex="-1">Three layers, three different jobs <a class="header-anchor" href="#three-layers-three-different-jobs" aria-label="Permalink to &quot;Three layers, three different jobs&quot;">​</a></h2><p>TMPA, FCoP, and CodeFlowMu are not three competing orchestration frameworks.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Role in this system</th><th>What it owns</th><th>What it does not own</th></tr></thead><tbody><tr><td>TMPA</td><td>Governance model</td><td>Stable identity, separation of responsibility, lifecycle legality, conflict preservation, deterministic reconstruction</td><td>Model execution, directories, or scheduling</td></tr><tr><td>FCoP</td><td>File state machine and coordination protocol</td><td>TASK, REPORT, ISSUE, and REVIEW artifacts; path-addressed state; transition events</td><td>Agent selection, tool execution, retry, or recovery policy</td></tr><tr><td>CodeFlowMu</td><td>Engineering rail</td><td>Roles, sessions, dispatch, capability checks, tool execution, observation, and technical recovery</td><td>The definition of TMPA or FCoP, or business acceptance on behalf of PM/ADMIN</td></tr></tbody></table><p>In compact form: <strong>TMPA defines governance semantics; FCoP externalizes state facts; CodeFlowMu keeps work moving on an engineering rail.</strong></p><p><img src="'+a+`" alt="TMPA defines governance semantics, FCoP fixes file state and events, and CodeFlowMu performs engineering execution"></p><p><em>Figure 1. Three layers of responsibility for an agent team. The diagram summarizes the verified boundaries in this article; it does not turn the protocol or the rail into interchangeable product claims. Source: author synthesis from the TMPA Architecture Paper, the FCoP v3 specification, and the CodeFlowMu V1.9.7 candidate evidence.</em></p><p>This separation also has an independent conceptual reference point. The W3C <a href="https://www.w3.org/TR/prov-o/" target="_blank" rel="noreferrer">PROV-O Recommendation</a> models entities, activities, and responsible agents separately, then connects them through generation, use, attribution, and delegation. PROV-O does not validate TMPA or CodeFlowMu. It does support a broader design lesson: an outcome, the activity that produced it, and the actor responsible for it should not collapse into one <code>done</code> flag.</p><h2 id="tmpa-defines-what-accountable-teamwork-means" tabindex="-1">TMPA defines what accountable teamwork means <a class="header-anchor" href="#tmpa-defines-what-accountable-teamwork-means" aria-label="Permalink to &quot;TMPA defines what accountable teamwork means&quot;">​</a></h2><p>The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/releases/tmpa/v1.0/artifacts/tmpa-architecture-paper-a1.0-en.md" target="_blank" rel="noreferrer">TMPA Architecture Paper A1.0</a> describes four operating ideas: text carries durable messages and state; each writer maintains a locally serial stream; multiple streams advance asynchronously; and a governance reader aggregates sources to reconstruct process and unresolved issues.</p><p>This is not a theory of how to make a model more intelligent. It addresses more basic questions:</p><ul><li>What stable object represents the work?</li><li>Who authored the task, report, review, and decision?</li><li>Was a lifecycle transition legal for that role?</li><li>When two sources conflict, does the system preserve the conflict or silently choose one?</li><li>Can responsibility and unfinished work be reconstructed after the original process disappears?</li></ul><p>The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/releases/tmpa/v1.0/artifacts/tmpa-core-specification-s1.0-en.md" target="_blank" rel="noreferrer">TMPA Core Specification S1.0</a> turns these ideas into testable objects and reader behavior. Stable primary carriers, single-writer objects, explicit references, role authority, and conflict preservation are central to that contract.</p><p>A governed team task therefore cannot exist only inside a chat transcript. The work needs a stable identity. Development evidence and QA review should remain attributable to their respective writers. Acceptance cannot be inserted casually into the executor&#39;s own report.</p><p>TMPA supplies the governance semantics. It does not require those objects to be stored in files rather than a database or object store.</p><h2 id="fcop-projects-governance-into-visible-state" tabindex="-1">FCoP projects governance into visible state <a class="header-anchor" href="#fcop-projects-governance-into-visible-state" aria-label="Permalink to &quot;FCoP projects governance into visible state&quot;">​</a></h2><p>FCoP uses the filesystem as a project-visible protocol substrate. Its current teaching statement is:</p><blockquote><p>Files carry protocol. Paths address state. Events replay transitions.</p></blockquote><p>A task occupies one lifecycle location:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inbox → active → review → done → archive</span></span>
<span class="line"><span>          ↑        │</span></span>
<span class="line"><span>          └ reject ┘</span></span>
<span class="line"><span>          └── finish ──→ done</span></span></code></pre></div><p>The path answers where the task is now. Append-only transition events explain how it got there. A TASK carries work intent, a REPORT carries an execution return, an ISSUE records a blocker or risk, and a REVIEW records an independent governance judgment. The exact current rules are in the <a href="https://github.com/joinwell52-AI/FCoP/blob/main/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a>.</p><p>The advantage is not that files are inherently reliable. It is that the state is inspectable by people, agents, and scripts without first decoding a private application database.</p><p>The boundary matters just as much. FCoP can declare <code>active → review</code> a legal transition, but it does not decide who should execute it or when. It defines a REPORT contract but does not start a model. It assumes one consistent filesystem boundary for a lifecycle root; it does not provide multi-host consensus.</p><p>There is an important concurrency boundary here. REPORT and REVIEW are separate artifacts, so they should not compete to overwrite the same report. Two callers competing to move the same TASK through its lifecycle are still competing, however. FCoP does not say that producing a REPORT automatically moves a task. Only L1 lifecycle tools may mutate <code>_lifecycle/</code>: <code>claim_task</code> moves <code>inbox</code> to <code>active</code>, and <code>submit_task</code> moves <code>active</code> to <code>review</code>. Within one filesystem boundary, the standard pattern writes event-augmented content to a temporary file in the destination directory, persists it, publishes the destination through <code>rename</code>, and only then removes the source. That gives destination publication an atomically visible commit point. It is not a global lock, and it does not automatically solve two concurrent claimants or multi-host writers.</p><p><code>rename</code> must therefore not run bare as a multi-claimant arbitration mechanism. If a future deployment supports independent Runtimes competing for the same TASK, its claim entry point needs a separate non-replaceable exclusive reservation or atomic compare-and-swap. Checking <code>expected_revision</code> before <code>rename</code> alone leaves a check-to-effect window and cannot guarantee exclusive claim. The primitive must be validated for its target host and filesystem. The current local-first, single-Runtime deployment does not claim to support shared-workspace contention or provide its stress test; this is an admission requirement for a future extension, not a claim about V1.9.7.</p><p>TMPA&#39;s “single-writer object” is therefore a responsibility-and-provenance constraint, not a synonym for “the filesystem has already locked it.” Nor is “each agent writes its own directory” a current FCoP guarantee.</p><p>A visible state machine still needs a system that performs the work.</p><h2 id="codeflowmu-turns-the-state-machine-into-a-running-rail" tabindex="-1">CodeFlowMu turns the state machine into a running rail <a class="header-anchor" href="#codeflowmu-turns-the-state-machine-into-a-running-rail" aria-label="Permalink to &quot;CodeFlowMu turns the state machine into a running rail&quot;">​</a></h2><p>CodeFlowMu is the engineering runtime in this stack. It connects roles, sessions, tasks, tools, reports, and recovery so that static coordination artifacts lead to controlled action.</p><p>In the V1.9.7 candidate parent implementation, the governance fact kernel keeps runtime facts, lifecycle, report, evidence, dependency, and acceptance as separate axes. Its canonical snapshot sets <code>business_decision</code> to <code>null</code>: the kernel may normalize facts and project available commands, but it does not manufacture a business verdict.</p><p>The rail-assistance contract also makes the decision owner explicit. The following is an equivalent narrow excerpt from the parent repository at fixed commit <code>2c901972</code>; the original type alias has been inlined for readability:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RailAssistanceResult</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  disposition</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;neutral&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;unknown_reconcile&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;waiting_dependency&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;negative_list_denied&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  decision_owner</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;AGENT&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;PM&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ADMIN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  facts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  advisories</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  suggested_actions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This is more than a UI label. The rail can return facts, cautions, and suggested actions. It can hold an operation for an explicit dependency or a frozen negative-list condition. A business judgment still comes back with an accountable owner.</p><p>The four dispositions have distinct meanings:</p><ul><li><code>neutral</code>: current facts are usable; the rail does not issue an allow-or-deny verdict for any role;</li><li><code>waiting_dependency</code>: an explicit prerequisite in the formal TASK is not satisfied, so the current operation may wait;</li><li><code>negative_list_denied</code>: a frozen negative condition—such as a scope, identity, or terminal-state conflict—requires rejection of the current operation;</li><li><code>unknown_reconcile</code>: available sources cannot yet be normalized into one usable context and must be reconciled. It does not mean the system has decided failure. A model must not turn missing or conflicting facts into an acceptance verdict; the Agent, PM, or ADMIN named by <code>decision_owner</code> decides how to obtain evidence, retry, or adjudicate.</li></ul><p>The current contract does not define <code>unknown_reconcile</code> as a fixed automatic rollback, circuit-breaker, quarantine queue, or notification flow. Those are caller and runtime policies; they cannot be inferred from this enum alone. If a high-risk downstream action cannot continue while sources conflict, the contract must explicitly make completed reconciliation a prerequisite, so the downstream action returns <code>waiting_dependency</code>; if an operation must be rejected, it must meet a pre-frozen deterministic condition. An enum name alone cannot promote unknown state into automatic quarantine or failure.</p><p>The dual-stage path conflict in Part 2, sources that cannot be normalized, and incomplete identity fields all enter this same <code>unknown_reconcile</code> disposition; they are not three parallel recovery mechanisms. A shared enum still does not make the operating mechanism complete. Unattended reconciliation needs at least a <code>reconcile_owner</code>, trigger reason, canonical task identity and revision, <code>opened_at</code>, a deadline, escalation route, and permitted terminal outcomes. A reconciling task must not keep waking a model and burning tokens. The V1.9.7 evidence does not establish a unified implementation of those fields, SLA, notification, or circuit breaker, so they remain admission requirements rather than current product claims.</p><p>The same version applies exact role/tool capability checks and routes PM task mutations through a shared task-command kernel. That kernel verifies task identity, scope, revision, and an idempotency key—a stable identifier used to coalesce transport retries of one business intent. These are deterministic software boundaries around who may act on which task; they are not prompt-based etiquette.</p><p>One cross-layer contract is still necessary: <strong>the dependency graph is a governance-bearing artifact, not ordinary execution data.</strong> An executing agent may report that an edge is wrong and propose a change, but it may not rewrite an existing TASK dependency merely because it is running. Dependency creation or mutation belongs to PM, ADMIN, or an actor explicitly delegated by the active governance policy. The change must create a new task revision, rerun identity, scope, and cycle checks, and preserve who changed which edge under which policy version. The inspected material does not prove that every dynamic dependency write path already enforces this contract, so the series does not claim that V1.9.7 has completed it.</p><h3 id="how-governance-reaches-implementation" tabindex="-1">How governance reaches implementation <a class="header-anchor" href="#how-governance-reaches-implementation" aria-label="Permalink to &quot;How governance reaches implementation&quot;">​</a></h3><p>TMPA rules cannot remain only in a paper, and they should not dissolve into untraceable <code>if</code> statements inside CodeFlowMu. The sound engineering boundary is a <strong>versioned governance policy bundle</strong> that names its policy ID, version, content digest, supported Runtime range, role and scope predicates, identity canonicalization, dependency-mutation authority, mechanical denial predicates, migration requirements, and rollback conditions. Every rail result should record the policy version it actually consumed.</p><p>Updateable does not mean silently hot-swappable in the middle of a run. One task round binds a stable policy. A new policy becomes effective only at a declared boundary after validation and ADMIN authorization. A concurrency patch follows the same rule: an exclusive reservation or compare-and-swap prevents two winners, while mapping a failed reservation to wait, denial, or reconciliation is governance semantics. An emergency fix may disable multi-claimant operation or contract the deployment to one Runtime. Changing who obtains execution authority or adding a mechanical denial requires the policy bundle and evidence matrix to change before the implementation does.</p><p>The capability gate is not a complete sandbox. Its own source states that it checks canonical tool identity and active capability, not every command effect. It can be a compliance filter for a collaboration contract; it cannot substitute for host-appropriate operating-system isolation such as restricted accounts, filesystem permissions, containers, or platform-native process isolation. If an agent has host access that can bypass the application layer, the gate alone cannot stop it from changing out-of-scope files or starting an unauthorized command. Treating a governance contract as a security sandbox is an architectural error. The inspected material does not prove that CodeFlowMu has deployed those isolation controls uniformly. The parent repository is private, so this article reproduces only the short contract required to explain the claim. It does not present private source as independently reproducible public evidence.</p><h2 id="one-work-item-across-all-three-layers" tabindex="-1">One work item across all three layers <a class="header-anchor" href="#one-work-item-across-all-three-layers" aria-label="Permalink to &quot;One work item across all three layers&quot;">​</a></h2><p>Consider a request to add CSV export to an existing product.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Input</th><th>Accountable actor</th><th>Output</th><th>Wait condition</th><th>Hard-denial condition</th><th>Reconcile / unknown</th></tr></thead><tbody><tr><td>Establish work</td><td>Approved requirement and acceptance criteria</td><td>PM / ADMIN</td><td>Stable root task and authority boundary</td><td>—</td><td>Invalid identity or authority scope</td><td>—</td></tr><tr><td>Create task</td><td>Recipient, dependencies, deliverables</td><td>FCoP L1 <code>create_task</code></td><td>TASK in <code>inbox</code></td><td>—</td><td>Invalid envelope or lifecycle location</td><td>—</td></tr><tr><td>Claim and bind execution</td><td>TASK in <code>inbox</code>, identity, and role capability</td><td>An authorized agent explicitly invokes FCoP L1 <code>claim_task</code>; CodeFlowMu may establish or schedule task context around it</td><td>TASK moves to <code>active</code> with an <code>inbox → active</code> event; the task is bound to an agent session</td><td>Explicit dependency pending → <code>waiting_dependency</code></td><td>Duplicate execution or missing role capability → reject this claim</td><td>Transition conflict → preserve and reconcile</td></tr><tr><td>Execute</td><td><code>active</code> TASK, code, and test environment</td><td>DEV / QA agent with CodeFlowMu Runtime</td><td>Code, raw test output, and execution explanation</td><td>—</td><td>Invalid tool capability or task scope</td><td>—</td></tr><tr><td>Write execution return</td><td>Code, raw test output, and execution explanation</td><td>Executor explicitly invokes FCoP <code>write_report</code></td><td>Attributable REPORT objects; for example, DEV and QA each write an independent envelope rather than overwriting one another; TASK remains in <code>active</code></td><td>—</td><td>—</td><td>Report identity or evidence conflict</td></tr><tr><td>Submit task for review</td><td><code>active</code> TASK and an already-written execution return</td><td>Executor explicitly invokes FCoP L1 <code>submit_task</code></td><td>TASK moves to <code>review</code> with an <code>active → review</code> event</td><td>—</td><td>An explicit submission precondition is unmet</td><td>Transition conflict → preserve and reconcile</td></tr><tr><td>Reconstruct facts</td><td>TASK, REPORT, lifecycle, provenance</td><td>Governance reader / fact kernel</td><td>Inspectable task snapshot and issue set</td><td>—</td><td>—</td><td>Missing or conflicting sources → <code>unknown_reconcile</code></td></tr><tr><td>Accept or rework</td><td>TASK in <code>review</code>, current revision, reports, and evidence</td><td>PM / ADMIN explicitly invokes <code>approve_task</code> or <code>reject_task</code></td><td>Move to <code>done</code>, or return to <code>active</code> for rework; an independent REVIEW remains a separate governance artifact</td><td>—</td><td>Wrong authority or stale target revision</td><td>—</td></tr></tbody></table><p>The last two stages are easy to compress incorrectly. A developer REPORT establishes that the developer submitted a result. The fact kernel observing that REPORT establishes that an attributable return exists. Neither fact decides whether the product requirement has been met.</p><p>The table describes an integration that respects the FCoP boundary. A runtime may provide work opportunity, sessions, and capability checks, but it must not turn “dispatch” into claiming on an agent&#39;s behalf. <code>write_report</code> produces a REPORT but does not automatically trigger <code>active → review</code>; only an explicit L1 call changes lifecycle location.</p><p>NIST&#39;s <a href="https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10" target="_blank" rel="noreferrer">AI RMF 1.0</a> treats governance as a cross-cutting lifecycle function and calls for explicit roles, responsibilities, and human oversight in human-AI configurations. It does not prescribe this three-layer architecture. It supports the general judgment that governance belongs inside the operating lifecycle, not on a dashboard added after completion.</p><h2 id="layering-does-not-mean-every-system-should-use-files" tabindex="-1">Layering does not mean every system should use files <a class="header-anchor" href="#layering-does-not-mean-every-system-should-use-files" aria-label="Permalink to &quot;Layering does not mean every system should use files&quot;">​</a></h2><p>This architecture is sometimes misread as a universal claim that all multi-agent systems should coordinate through local files. Neither TMPA nor this article makes that claim.</p><p>Within one project root, one consistent filesystem, and a controlled writer boundary, the inspectability and low infrastructure cost of an FCoP profile are valuable. Multi-host writers, relaxed network filesystems, cross-trust-domain operation, or strong consistency requirements need an additional consistency layer and may be better served by a database or event service. The TMPA governance semantics may remain useful even when the file profile does not.</p><p>There is also a simpler counterexample. If three agents are brainstorming in a low-risk, one-off session with no external effects, a complete governed lifecycle may cost more than it saves. Governance depth should track duration, conflict risk, reversibility, and acceptance responsibility.</p><h2 id="what-remains-between-one-runtime-and-concurrent-production" tabindex="-1">What remains between one Runtime and concurrent production <a class="header-anchor" href="#what-remains-between-one-runtime-and-concurrent-production" aria-label="Permalink to &quot;What remains between one Runtime and concurrent production&quot;">​</a></h2><p>“Not currently supported” cannot be the permanent answer to concurrency. A candid roadmap separates consistency boundaries:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Target topology</th><th>New admission evidence required</th></tr></thead><tbody><tr><td>Current</td><td>One machine, one project root, one Runtime writer</td><td>Restart recovery, root binding, writer lock, and existing regression</td></tr><tr><td>Next</td><td>Multiple processes competing for one task on one host</td><td>Non-replaceable claim, zero loser-side effects, lease/reclamation, contention stress, and fault injection</td></tr><tr><td>Later</td><td>Multiple Runtimes sharing one local filesystem</td><td>Exclusive canonical-task claim, policy-version agreement, preserved write conflict, repeatable recovery</td></tr><tr><td>Multi-host</td><td>Network filesystem or cross-trust domain</td><td>A separate consistency profile, failure model, and authority model; local <code>rename</code> results cannot simply be carried over</td></tr></tbody></table><p>CodeFlowMu&#39;s digital-employee direction will encounter multi-instance production. Crossing that boundary requires a new protocol profile, policy version, and test evidence—not merely removing the words “local-first.”</p><h2 id="seven-questions-for-your-architecture" tabindex="-1">Seven questions for your architecture <a class="header-anchor" href="#seven-questions-for-your-architecture" aria-label="Permalink to &quot;Seven questions for your architecture&quot;">​</a></h2><ol><li>Does each work item have a stable identity independent of a model session?</li><li>Are current state, history, execution return, and acceptance separate facts?</li><li>Can each report be traced to a task, attempt, and accountable role?</li><li>Does the system preserve conflicts rather than overwrite them silently?</li><li>Has the protocol layer or runtime overreached by taking acceptance, rework, or a final conclusion away from the accountable business role?</li><li>Does the runtime enforce mechanical boundaries while leaving acceptance to an authorized actor?</li><li>Can unfinished work be reconstructed after the original session or process disappears?</li></ol><p>If the answer to these questions is only “the prompt tells the agents to be careful,” the system still has multiple sessions, not a governed team.</p><p>Evidence boundaries remain important. The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/releases/tmpa/v1.0/artifacts/tmpa-implementation-case-i1.0-en.md" target="_blank" rel="noreferrer">TMPA Implementation Case I1.0</a> records an author-run CodeFlowMu V1.8.0 product reader against a fixed S1.0 bundle. The V1.9.7 candidate has separate current-source, regression, and live-restart evidence. Version files and the live process report V1.9.7, but that does not make the release note&#39;s candidate status a final <code>RELEASED</code> decision; ADMIN still owns that decision. Together these records support bounded engineering feasibility; neither is third-party certification or a universal cross-platform proof.</p><p>The next validation step has two tracks. The public track must not depend on a private runtime: use the published <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s1.0" target="_blank" rel="noreferrer">TMPA S1.0 conformance artifacts and reference reader</a> together with the FCoP specification and reference tools. Inject source conflicts into fixed TASK, REPORT, and REVIEW artifacts, then check whether identity, provenance, and conflict preservation reconstruct consistently. That tests governance and protocol semantics; it does not replace verification of CodeFlowMu&#39;s private rail. The restricted track is for an independent environment authorized to access the V1.9.7 candidate parent implementation: replay stale-revision commands, task contention, and Runtime restart tests. Until a public reproducer exists, outside readers cannot reproduce the product-level conclusion themselves.</p><p>The reusable lesson is not the three project names. It is the chain of responsibility: <strong>the governance model defines legitimacy, the state machine preserves facts, the rail executes and recovers, and an accountable actor makes the final judgment.</strong></p><h2 id="sources-and-evidence-boundaries" tabindex="-1">Sources and evidence boundaries <a class="header-anchor" href="#sources-and-evidence-boundaries" aria-label="Permalink to &quot;Sources and evidence boundaries&quot;">​</a></h2><p>For how this series distinguishes public specifications, private code excerpts, first-party execution records, and independent material, see <a href="./../methodology/evidence-boundaries">How to Read Engineering Evidence at the Digital Employee Works</a>. The sources below still support only the specific claims stated in this article.</p><ul><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/releases/tmpa/v1.0/artifacts/tmpa-architecture-paper-a1.0-en.md" target="_blank" rel="noreferrer">TMPA Architecture Paper A1.0</a>, <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/releases/tmpa/v1.0/artifacts/tmpa-core-specification-s1.0-en.md" target="_blank" rel="noreferrer">TMPA Core S1.0</a>, and the <a href="https://github.com/joinwell52-AI/FCoP/blob/main/spec/fcop-3.0-spec.md" target="_blank" rel="noreferrer">FCoP 3.0 specification</a> support the account of this research&#39;s governance objects, file artifacts, and lifecycle semantics; they do not constitute public reproduction of a private runtime.</li><li><a href="https://www.w3.org/TR/prov-o/" target="_blank" rel="noreferrer">W3C PROV-O</a> is an independent reference for separating entities, activities, and responsible agents. It does not specify TMPA/FCoP paths or envelopes.</li><li><a href="https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10" target="_blank" rel="noreferrer">NIST AI RMF 1.0</a> supports the general governance context of roles and oversight throughout the lifecycle. It neither endorses nor certifies this implementation.</li><li>V1.9.7 runtime figures are first-party, controlled evidence and support only the recorded Windows environment, code, and test set. Accessed 2026-08-23.</li></ul>`,71))])}const v=n(l,[["render",d]]);export{b as __pageData,v as default};
